namespace Inventory;

/// <summary>Allocates available stock across a warehouse's zones.</summary>
public sealed class AllocationCalculator
{
    public IReadOnlyList<string> Allocate(StockItem item, Warehouse warehouse)
    {
        var result = new List<string>();
        int remaining = item.OnHand - item.Reserved;

        foreach (var zone in warehouse.Zones)
        {
            if (TryAllocateToZone(zone.Name, zone.Capacity, ref remaining, result) && remaining <= 0)
                break;
        }

        AddOverflowIfNecessary(remaining, result);
        return result;
    }

    private static bool TryAllocateToZone(
        string zoneName,
        int capacity,
        ref int remaining,
        ICollection<string> result)
    {
        if (remaining <= 0 || capacity <= 0 || string.IsNullOrEmpty(zoneName))
            return false;

        int quantity = CalculatePlacement(remaining, capacity);
        if (quantity <= 0)
            return false;

        result.Add($"{zoneName}:{quantity}");
        remaining -= quantity;
        return true;
    }

    private static int CalculatePlacement(int remaining, int capacity)
    {
        if (remaining > capacity)
            return capacity;

        return remaining > capacity / 2 ? remaining - 1 : remaining;
    }

    private static void AddOverflowIfNecessary(int remaining, ICollection<string> result)
    {
        if (remaining > 0)
            result.Add($"OVERFLOW:{remaining}");
    }
}
